{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "segments" not in case or "budget" not in case:
        raise ValueError("missing required case field")
    segments = case["segments"]
    budget = case["budget"]
    if not isinstance(segments, list):
        raise ValueError("segments must be a list")
    if isinstance(budget, bool) or not isinstance(budget, int):
        raise ValueError("budget must be an integer")

    names = []
    importances = []
    allocations = []
    capacities = []
    seen_names = set()
    for segment in segments:
        if not isinstance(segment, dict):
            raise ValueError("each segment must be an object")
        for field in ("name", "importance", "minimum", "capacity"):
            if field not in segment:
                raise ValueError("missing required segment field")
        name = segment["name"]
        importance = segment["importance"]
        minimum = segment["minimum"]
        capacity = segment["capacity"]
        if not isinstance(name, str):
            raise ValueError("segment name must be a string")
        if name in seen_names:
            raise ValueError("segment names must be unique")
        if (isinstance(importance, bool) or not isinstance(importance, int) or
                isinstance(minimum, bool) or not isinstance(minimum, int) or
                isinstance(capacity, bool) or not isinstance(capacity, int)):
            raise ValueError("segment numeric fields must be integers")
        if importance < 0 or minimum < 0 or capacity < minimum:
            raise ValueError("invalid segment bounds")
        seen_names.add(name)
        names.append(name)
        importances.append(importance)
        allocations.append(minimum)
        capacities.append(capacity)

    quota_sum = sum(allocations)
    capacity_sum = sum(capacities)
    if budget < quota_sum or budget > capacity_sum:
        raise ValueError("budget is outside feasible bounds")

    remaining = budget - quota_sum
    while remaining:
        best = None
        for index in range(len(allocations)):
            if allocations[index] >= capacities[index]:
                continue
            if best is None:
                best = index
                continue
            if importances[index] * (allocations[best] + 1) > importances[best] * (allocations[index] + 1):
                best = index
        allocations[best] += 1
        remaining -= 1

    return {
        "allocations": allocations,
        "by_name": {name: allocation for name, allocation in zip(names, allocations)},
        "total": sum(allocations),
    }
"}
